CREATE OR REPLACE FUNCTION public.validate_application_text() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE field record; value_text text; record_json jsonb := to_jsonb(NEW); BEGIN FOR field IN SELECT key,value FROM jsonb_each(record_json) LOOP IF jsonb_typeof(field.value)='string' AND field.key<>'signature_image' THEN value_text:=field.value #>> '{}'; IF length(value_text)>10000 OR value_text ~* '<[[:space:]]*[/!?a-z]' OR value_text ~* '(javascript|vbscript)[[:space:]]*:' THEN RAISE EXCEPTION 'Text must be plain text and within length limits' USING ERRCODE='22023'; END IF; END IF; END LOOP; IF TG_TABLE_NAME IN ('profiles','job_posts','nail_trade_items','insurance_leads','health_declarations') THEN value_text:=record_json->>'phone'; IF value_text IS NOT NULL AND value_text<>'' AND value_text !~ '^\+?[0-9 ()-]{7,30}$' THEN RAISE EXCEPTION 'Invalid phone number' USING ERRCODE='22023'; END IF; END IF; IF TG_TABLE_NAME='model_calls' THEN value_text:=record_json->>'contact'; IF value_text !~ '^\+?[0-9 ()-]{7,30}$' AND value_text !~ '^https://wa\.me/[0-9]{8,15}$' AND value_text !~ '^https://api\.whatsapp\.com/send\?phone=[0-9]{8,15}$' THEN RAISE EXCEPTION 'Invalid WhatsApp contact' USING ERRCODE='22023'; END IF; END IF; IF TG_TABLE_NAME='role_change_requests' AND TG_OP='INSERT' THEN IF record_json->>'status'<>'pending' THEN RAISE EXCEPTION 'Requests must start pending' USING ERRCODE='22023'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.validate_tool_inputs() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); BEGIN IF TG_TABLE_NAME='health_declarations' THEN IF j->>'id_number' !~ '^[0-9]{9}$' OR length(j->>'signature_image')>500000 OR j->>'signature_image' !~ '^data:image/png;base64,[A-Za-z0-9+/=]+$' THEN RAISE EXCEPTION 'Invalid identity or signature' USING ERRCODE='22023'; END IF; ELSIF TG_TABLE_NAME='insurance_leads' THEN IF j->>'id_number' !~ '^[0-9]{9}$' OR (j->>'equipment_value_nis')::numeric<0 OR j->>'email' !~ '^[^ @]+@[^ @]+\.[^ @]+$' THEN RAISE EXCEPTION 'Invalid insurance input' USING ERRCODE='22023'; END IF; END IF; RETURN NEW; END $$;